// Heurística de Nielsen 4: 50 problemas aprofundados pela UBERTRIZ
window.PROBLEMAS.push(
{"id":151,"h":4,"sev":3,"t":"Mesma ação, nomes diferentes","sym":"No ERP da empresa, uma tela diz “Salvar”, outra “Gravar”, outra “Confirmar” — para a mesma coisa.","ten":"Cada equipe escreve do seu jeito, mas quem usa percebe um produto só.","sol":"Glossário da interface e design system com rótulos padronizados e revisados.","c":"C35","u":"U30","e":"macro","i":"I03","m":"Inconsistências por auditoria","freq":3,"imp":1,"pers":3,"pf":"P08","hx":["SH1","BS6","DN5","TG4","ISO3","GP5"],"dom":"trabalho","vul":"","ag":"Ganha: quem usa o sistema e quem escreve para ele. Perde: equipes perdem liberdade de nomear.","alt":"E se os sinônimos indicarem ações realmente diferentes (salvar rascunho × confirmar envio)? Então a unificação apagaria uma diferença real.","esc":{"micro":"Revisar os rótulos das telas mais usadas.","meso":"Glossário de interface aplicado por fluxo.","macro":"Glossário da interface e design system com rótulos padronizados e revisados."},"st":"sub","sub":"A própria solução é subtrativa: elimina os sinônimos e deixa um termo por ação.","ops":["U35","U36"],"c2":{"c":"C23","t":"Um termo único pode não servir a todos os contextos (salvar ≠ enviar).","mit":"Um termo por ação distinta, documentado com exemplos."},"cf":"Sem intervenção, a pessoa duvida se “Gravar” e “Salvar” fazem a mesma coisa e hesita em cada tela.","lim":{"l":"L06","t":"Exige governança entre equipes de produto."},"ide":{"mais":["I03","I04"],"menos":["I07"]},"ref":"Estaria errada se os rótulos diferentes corresponderem a ações diferentes no sistema.","conf":"alta"},
{"id":152,"h":4,"sev":3,"t":"Botão principal muda de lugar","sym":"Em uma tela o “Continuar” fica à direita; na seguinte, à esquerda.","ten":"Cada layout foi pensado isoladamente, mas o hábito da mão exige posição fixa.","sol":"Separar no espaço: uma zona fixa para a ação principal em todas as telas, com hierarquia visual única.","c":"C32","u":"U07","e":"meso","i":"I04","m":"Cliques na ação errada","freq":3,"imp":2,"pers":2,"pf":"P01","hx":["SH1","BS6","DN5","TG4","LX4","MB3"],"dom":"comercio","vul":"","ag":"Ganha: quem compra, sobretudo no celular. Perde: designers perdem liberdade de layout por tela.","alt":"E se o problema for haver ações principais demais disputando o mesmo lugar?","esc":{"micro":"Botão principal com estilo único.","meso":"Separar no espaço: uma zona fixa para a ação principal em todas as telas, com hierarquia visual única.","macro":"Regra no design system: zona fixa para a ação principal em todos os fluxos."},"st":"mod","sub":"Retirar ações secundárias da zona reservada à ação principal.","ops":["U30","U36"],"c2":{"c":"C24","t":"Em telas muito diferentes, a posição fixa pode ficar longe do conteúdo.","mit":"Barra de ação fixa no rodapé em telas pequenas."},"cf":"Sem intervenção, cliques em “Voltar” no lugar de “Continuar” e abandono do checkout.","lim":{"l":"L06","t":"Depende de todas as equipes seguirem o padrão."},"ide":{"mais":["I04"],"menos":["I08"]},"ref":"Estaria errada se os cliques errados vierem de botões pequenos, e não de posição variável.","conf":"alta"},
{"id":153,"h":4,"sev":3,"t":"Link que não parece link","sym":"No portal público, texto clicável tem quase a mesma cor do texto comum; ninguém descobre os links.","ten":"O visual quer ser limpo, mas o que é clicável precisa se anunciar.","sol":"Separar funções visuais: links com cor e sublinhado, diferentes de texto e de botões.","c":"C02","u":"U09","e":"micro","i":"I03","m":"Descoberta de links em teste","freq":3,"imp":2,"pers":2,"pf":"P01","hx":["WC1.4","DN7","DN6","BS1.3","TG6","GP9"],"dom":"publico","vul":"baixa visão","ag":"Ganha: cidadãos, sobretudo com baixa visão ou daltonismo. Perde: parte da limpeza visual do texto.","alt":"E se houver links demais no texto, e o problema for de redação?","esc":{"micro":"Separar funções visuais: links com cor e sublinhado, diferentes de texto e de botões.","meso":"Links, botões e texto com estilos claramente distintos em todo o portal.","macro":"Guia de conteúdo: links descritivos e em quantidade moderada."},"st":"mod","sub":"Retirar links do meio de parágrafos quando puderem virar uma lista de “Veja também”.","ops":["U01","U30"],"c2":{"c":"C17","t":"Sublinhados em excesso cansam a leitura.","mit":"Sublinhado só em links no corpo do texto; menus sem sublinhado."},"cf":"Sem intervenção, serviços ficam invisíveis para quem não percebe a diferença de cor.","lim":{"l":"L03","t":"Nenhuma barreira técnica; depende do CSS global."},"ide":{"mais":["I03","I06"],"menos":[]},"ref":"Estaria errada se, em teste, as pessoas encontrarem os links pela mudança do cursor.","conf":"alta"},
{"id":154,"h":4,"sev":3,"t":"Um ícone, dois significados","sym":"No ambiente acadêmico, o lápis significa “editar” numa tela e “assinar” em outra.","ten":"Reaproveitar ícones economiza, mas quebra o significado aprendido.","sol":"Um ícone, um significado; inventário e auditoria de ícones do produto.","c":"C08","u":"U09","e":"micro","i":"I04","m":"Erros de ação por ícone","freq":2,"imp":2,"pers":2,"pf":"P01","hx":["BS7","SH1","GP5","DN5","TG4"],"dom":"educacao","vul":"","ag":"Ganha: estudantes e professores. Perde: nada relevante.","alt":"E se “assinar” nem precisar de ícone próprio?","esc":{"micro":"Um ícone, um significado; inventário e auditoria de ícones do produto.","meso":"Inventário de ícones da plataforma com um significado cada.","macro":"Biblioteca de ícones governada, com revisão ao adicionar novos."},"st":"sub","sub":"A própria solução é subtrativa: tira o lápis de “assinar” e deixa só o rótulo.","ops":["U35","U30"],"c2":{"c":"C16","t":"Ícones exclusivos para cada ação exigem muitos ícones.","mit":"Rótulo textual onde não houver ícone reconhecível."},"cf":"Sem intervenção, estudantes assinam documentos quando queriam editar.","lim":{"l":"L06","t":"Depende de governança sobre a biblioteca de ícones."},"ide":{"mais":["I04"],"menos":[]},"ref":"Estaria errada se as pessoas lerem o rótulo e não se guiarem pelo ícone.","conf":"alta"},
{"id":155,"h":4,"sev":3,"t":"Ignorar convenções da plataforma","sym":"O logotipo não leva ao início, o carrinho fica no rodapé, o gesto de voltar não funciona.","ten":"O produto quer ser original, mas as pessoas trazem hábitos de outros sites e apps.","sol":"Condicionar pelas convenções: seguir os padrões da plataforma e de outras lojas, inovando só onde houver ganho.","c":"C29","u":"U21","e":"macro","i":"I08","m":"Tempo de adaptação de novos usuários","freq":3,"imp":2,"pers":2,"pf":"P14","hx":["LX4","SH1","ISO3","MB3","TG4","BS8"],"dom":"comercio","vul":"","ag":"Ganha: quem compra, que já conhece outras lojas. Perde: a marca perde parte de sua “originalidade”.","alt":"E se a inovação trouxer ganho real? Então ela precisa ser ensinada, não imposta.","esc":{"micro":"Logotipo que leva ao início.","meso":"Carrinho no canto superior direito e gestos nativos.","macro":"Condicionar pelas convenções: seguir os padrões da plataforma e de outras lojas, inovando só onde houver ganho."},"st":"mod","sub":"Retirar inovações que só trocam convenções de lugar sem ganho.","ops":["U26","U04"],"c2":{"c":"C20","t":"Seguir convenções limita a diferenciação da marca.","mit":"Inovar no conteúdo e no serviço, não nos controles."},"cf":"Sem intervenção, novos clientes demoram a se adaptar e desistem.","lim":{"l":"L07","t":"Hábitos formados em outros sites."},"ide":{"mais":["I08"],"menos":["I12"]},"ref":"Estaria errada se, em teste, o padrão próprio for aprendido rapidamente.","conf":"alta"},
{"id":156,"h":4,"sev":3,"t":"Cada módulo com sua tabela","sym":"Relatórios, vendas e estoque têm tabelas com ordenação e filtros diferentes.","ten":"Equipes independentes entregam mais rápido, mas criam interfaces divergentes.","sol":"Reacoplar: um componente de tabela compartilhado no design system, consumido por todos os módulos.","c":"C12","u":"U12","e":"macro","i":"I11","m":"Componentes duplicados no código","freq":2,"imp":2,"pers":3,"pf":"P08","hx":["SH1","BS6","DN5","TG4","ISO3"],"dom":"trabalho","vul":"","ag":"Ganha: quem usa vários módulos e quem mantém o sistema. Perde: equipes perdem autonomia de componente.","alt":"E se as tabelas precisarem de funções diferentes por módulo?","esc":{"micro":"Mesmo estilo visual em todas as tabelas.","meso":"Componente de tabela compartilhado com extensões por módulo.","macro":"Reacoplar: um componente de tabela compartilhado no design system, consumido por todos os módulos."},"st":"sub","sub":"A própria solução é subtrativa: remove as cópias locais de tabela.","ops":["U35","U31"],"c2":{"c":"C12","t":"Um componente central vira dependência crítica: um erro afeta todo o sistema.","mit":"Testes automatizados e versões."},"cf":"Sem intervenção, cada tela ensina uma tabela diferente e a manutenção multiplica.","lim":{"l":"L04","t":"Migrar módulos antigos exige tempo de desenvolvimento."},"ide":{"mais":["I11","I03"],"menos":["I07"]},"ref":"Estaria errada se as diferenças atenderem a necessidades reais de cada módulo.","conf":"alta"},
{"id":157,"h":4,"sev":3,"t":"App e e-mail falam línguas diferentes","sym":"No app é “Reserva”; no e-mail, “Localizador PNR”.","ten":"Canais feitos por equipes diferentes, mas vistos pela mesma pessoa.","sol":"Vocabulário único em todos os canais: app, site, e-mail, SMS e suporte.","c":"C11","u":"U30","e":"macro","i":"I03","m":"Contatos por confusão de termos","freq":2,"imp":2,"pers":2,"pf":"P08","hx":["SH1","BS6","ISO3","GP5"],"dom":"mobilidade","vul":"","ag":"Ganha: viajantes. Perde: cada canal perde liberdade de vocabulário.","alt":"E se os canais forem de empresas diferentes (companhia e agência)?","esc":{"micro":"Revisar os e-mails mais enviados.","meso":"Vocabulário único nos fluxos de reserva.","macro":"Vocabulário único em todos os canais: app, site, e-mail, SMS e suporte."},"st":"mod","sub":"Retirar termos internos (“Ordem”, “PNR”) das mensagens ao cliente.","ops":["U04","U36"],"c2":{"c":"C21","t":"O vocabulário muda com o tempo e os canais se desalinham de novo.","mit":"Revisão periódica e glossário compartilhado."},"cf":"Sem intervenção, o cliente acha que tem duas reservas diferentes e liga para a central.","lim":{"l":"L06","t":"Depende de acordos entre equipes e parceiros."},"ide":{"mais":["I03"],"menos":[]},"ref":"Estaria errada se os clientes não notarem a diferença.","conf":"alta"},
{"id":158,"h":4,"sev":4,"t":"Cor que contradiz o significado","sym":"No app do banco, o botão “Excluir conta” é verde; o “Salvar” é vermelho.","ten":"A cor foi escolhida pela marca, mas carrega significado próprio.","sol":"Instituir tokens semânticos: vermelho só para ações destrutivas e erros, verde para sucesso.","c":"C02","u":"U30","e":"micro","i":"I05","m":"Ações destrutivas acidentais","freq":2,"imp":3,"pers":2,"pf":"P01","hx":["TG3","BS1.3","DN5","GP9","SH5"],"dom":"financas","vul":"","ag":"Ganha: clientes. Perde: a marca perde uso livre de cores.","alt":"E se a cor da marca for verde? Então o conflito é com a identidade, não com o botão.","esc":{"micro":"Instituir tokens semânticos: vermelho só para ações destrutivas e erros, verde para sucesso.","meso":"Tokens semânticos aplicados em todo o app.","macro":"Guia de marca com cores reservadas para significado."},"st":"mod","sub":"Retirar a cor da marca dos botões destrutivos.","ops":["U22","U17"],"c2":{"c":"C20","t":"A marca verde perde espaço em áreas de destaque.","mit":"Marca em elementos neutros, semânticos nos botões."},"cf":"Sem intervenção, clientes excluem a conta achando que estavam confirmando algo.","lim":{"l":"L06","t":"Diretrizes de marca que reservam o verde para a identidade visual."},"ide":{"mais":["I05"],"menos":["I08"]},"ref":"Estaria errada se, em teste com o botão verde, ninguém excluir a conta por engano.","conf":"alta"},
{"id":159,"h":4,"sev":3,"t":"Atalho que muda de função","sym":"Ctrl+S salva numa tela e exporta PDF em outra.","ten":"Cada tela quer seus atalhos, mas a memória muscular é global.","sol":"Memorizar o hábito: um mapa de atalhos único para o produto, visível nos menus.","c":"C05","u":"U36","e":"meso","i":"I04","m":"Uso errado de atalhos","freq":2,"imp":2,"pers":2,"pf":"P01","hx":["SH1","BS6","DN5","BS4.2","ISO3"],"dom":"trabalho","vul":"","ag":"Ganha: quem usa atalhos. Perde: telas perdem atalhos próprios.","alt":"E se o atalho diferente existir porque a tela não tem “salvar”?","esc":{"micro":"Atalho com a mesma função em todas as telas.","meso":"Memorizar o hábito: um mapa de atalhos único para o produto, visível nos menus.","macro":"Mapa de atalhos da plataforma, documentado."},"st":"mod","sub":"Retirar atalhos locais que conflitam com os globais.","ops":["U30","U01"],"c2":{"c":"C16","t":"Poucas combinações de teclas livres para ações locais.","mit":"Prefixo de atalho para funções locais."},"cf":"Sem intervenção, a pessoa exporta um PDF quando queria salvar e perde tempo.","lim":{"l":"L03","t":"Atalhos reservados pelo navegador e sistema."},"ide":{"mais":["I04"],"menos":["I08"]},"ref":"Estaria errada se os registros mostrarem que quase ninguém usa atalhos de teclado no sistema.","conf":"alta"},
{"id":160,"h":4,"sev":3,"t":"Datas em formatos diferentes","sym":"No prontuário, uma tela mostra “22/09/2026”, outra “Sep 22”, outra “2026-09-22”.","ten":"Cada tela formata por conta própria, mas a informação é a mesma.","sol":"Selecionar um só formato e um formatador central, removendo os demais.","c":"C35","u":"U35","e":"meso","i":"I04","m":"Formatos distintos encontrados","freq":2,"imp":2,"pers":2,"pf":"P01","hx":["SH1","BS6","GP6","ISO3"],"dom":"saude","vul":"","ag":"Ganha: equipes de saúde. Perde: nada relevante.","alt":"E se formatos diferentes servirem a usos diferentes?","esc":{"micro":"Um formato padrão nas telas do prontuário.","meso":"Selecionar um só formato e um formatador central, removendo os demais.","macro":"Formatador central para todos os sistemas da rede."},"st":"sub","sub":"A própria solução é subtrativa: elimina os formatadores locais.","ops":["U12","U30"],"c2":{"c":"C29","t":"Relatórios exportados para outros sistemas precisam de formato técnico.","mit":"Formato ISO só nos arquivos exportados."},"cf":"Sem intervenção, datas são lidas trocadas e medicações são registradas no dia errado.","lim":{"l":"L03","t":"Depende de refatorar telas antigas."},"ide":{"mais":["I04"],"menos":[]},"ref":"Estaria errada se as datas diferentes não causarem erros de leitura.","conf":"alta"},
{"id":161,"h":4,"sev":2,"t":"Botão de fechar que muda de canto","sym":"No ambiente virtual, o “×” dos modais fica à direita em uns e à esquerda em outros.","ten":"Cada modal foi desenhado isoladamente, mas o olho procura sempre o mesmo lugar.","sol":"Reacoplar num componente único de modal, com o fechar sempre no mesmo canto.","c":"C09","u":"U12","e":"meso","i":"I04","m":"Tempo para fechar modais","freq":2,"imp":1,"pers":2,"pf":"P01","hx":["SH1","DN5","BS6","TG4"],"dom":"educacao","vul":"","ag":"Ganha: estudantes. Perde: nada relevante.","alt":"E se o modal em si for desnecessário em parte das telas?","esc":{"micro":"Mesmo ícone e posição de fechar.","meso":"Reacoplar num componente único de modal, com o fechar sempre no mesmo canto.","macro":"Componente de modal no design system."},"st":"sub","sub":"A própria solução é subtrativa: remove as variantes de modal.","ops":["U35","U30"],"c2":{"c":"C12","t":"Um componente único exige migração de telas antigas.","mit":"Migração gradual, começando pelos modais mais usados."},"cf":"Sem intervenção, estudantes procuram o fechar a cada janela.","lim":{"l":"L04","t":"Tempo de migração das telas antigas para o componente novo."},"ide":{"mais":["I04"],"menos":[]},"ref":"Estaria errada se o tempo para fechar modais for igual nas duas posições do botão.","conf":"alta"},
{"id":162,"h":4,"sev":4,"t":"Ordem de confirmar e cancelar invertida","sym":"No app do banco, em um diálogo “Confirmar” está à direita; no próximo, à esquerda.","ten":"A mão aprende a posição, e a inversão provoca a ação errada.","sol":"Ordem fixa em todo o produto, seguindo a convenção da plataforma.","c":"C32","u":"U30","e":"meso","i":"I04","m":"Confirmações acidentais","freq":3,"imp":3,"pers":2,"pf":"P01","hx":["SH1","SH5","BS6","DN5","LX4"],"dom":"financas","vul":"idosos","ag":"Ganha: clientes, sobretudo idosos. Perde: nada relevante.","alt":"E se a confirmação for desnecessária em parte dos diálogos?","esc":{"micro":"Ordem fixa nos diálogos de transferência.","meso":"Ordem fixa em todo o produto, seguindo a convenção da plataforma.","macro":"Regra de ordem de botões seguindo a plataforma."},"st":"mod","sub":"Retirar diálogos de confirmação que o desfazer já substitui.","ops":["U36","U24"],"c2":{"c":"C29","t":"iOS e Android usam ordens diferentes.","mit":"Seguir a convenção de cada plataforma, sempre igual dentro dela."},"cf":"Sem intervenção, confirmações acidentais de transferências.","lim":{"l":"L07","t":"Memória motora formada em outros apps."},"ide":{"mais":["I04"],"menos":[]},"ref":"Estaria errada se os erros vierem de rótulos ambíguos, e não da ordem.","conf":"alta"},
{"id":163,"h":4,"sev":3,"t":"Botão secundário parece desabilitado","sym":"No app da casa, o botão “Agendar” é cinza-claro e as pessoas acham que não funciona.","ten":"O secundário deve pesar menos, mas não pode parecer inativo.","sol":"Separar os estilos: secundário com contorno; desabilitado esmaecido e sem cursor de clique.","c":"C03","u":"U09","e":"micro","i":"I03","m":"Cliques em ações secundárias","freq":2,"imp":2,"pers":2,"pf":"P01","hx":["BS1.3","DN7","SH1","TG4","WC1.4"],"dom":"casa","vul":"","ag":"Ganha: quem configura a casa. Perde: nada relevante.","alt":"E se o secundário for pouco usado e devesse ir para um menu?","esc":{"micro":"Separar os estilos: secundário com contorno; desabilitado esmaecido e sem cursor de clique.","meso":"Estilos de botão definidos por hierarquia no design system.","macro":"Guia de estados (normal, secundário, desabilitado) com exemplos."},"st":"mod","sub":"Retirar o cinza claro dos botões secundários.","ops":["U30","U01"],"c2":{"c":"C17","t":"Secundários mais visíveis competem com o principal.","mit":"Contorno, sem preenchimento."},"cf":"Sem intervenção, funções secundárias parecem quebradas.","lim":{"l":"L03","t":"Nenhuma barreira técnica."},"ide":{"mais":["I03"],"menos":[]},"ref":"Estaria errada se, em teste, as pessoas clicarem nos secundários sem dúvida.","conf":"alta"},
{"id":164,"h":4,"sev":2,"t":"Telefones em formatos variados","sym":"Na agenda de contatos, a lista mostra “11987654321”, “(11) 98765-4321” e “+55 11 9 8765 4321”.","ten":"Cada entrada veio de uma fonte, mas a leitura exige uniformidade.","sol":"Normalizar ao salvar e exibir sempre no mesmo formato.","c":"C15","u":"U12","e":"micro","i":"I04","m":"Duplicidades por formato","freq":2,"imp":1,"pers":2,"pf":"P01","hx":["SH1","BS6","GP6","LX7"],"dom":"comunicacao","vul":"","ag":"Ganha: quem gerencia contatos. Perde: nada relevante.","alt":"E se os números duplicados vierem de fontes diferentes (importação, sincronização)?","esc":{"micro":"Normalizar ao salvar e exibir sempre no mesmo formato.","meso":"Normalização na importação de contatos.","macro":"Padrão de telefone em toda a plataforma."},"st":"mod","sub":"Retirar formatações salvas junto com o número.","ops":["U16","U02"],"c2":{"c":"C09","t":"Normalizar pode errar números estrangeiros.","mit":"Detectar o país pelo código e preservar números estrangeiros como vieram."},"cf":"Sem intervenção, contatos duplicados e buscas que falham.","lim":{"l":"L03","t":"Números antigos em formatos imprevisíveis."},"ide":{"mais":["I04"],"menos":[]},"ref":"Estaria errada se as buscas funcionarem apesar dos formatos.","conf":"alta"},
{"id":165,"h":4,"sev":2,"t":"Maiúsculas aleatórias nos títulos","sym":"“Minha Conta”, “meus pedidos”, “CONFIGURAÇÕES”.","ten":"Cada tela foi escrita por uma pessoa diferente.","sol":"Retroalimentar a escrita: regra única de capitalização verificada automaticamente antes de publicar.","c":"C06","u":"U19","e":"micro","i":"I03","m":"Inconsistências por auditoria","freq":1,"imp":1,"pers":3,"pf":"P01","hx":["SH1","BS6","BS1.5","TG14"],"dom":"publico","vul":"dislexia","ag":"Ganha: leitores, sobretudo com dislexia. Perde: nada relevante.","alt":"E se a caixa alta for usada para destacar, por falta de outra ênfase?","esc":{"micro":"Retroalimentar a escrita: regra única de capitalização verificada automaticamente antes de publicar.","meso":"Revisão automática de textos antes de publicar.","macro":"Guia de escrita do órgão com regra de capitalização."},"st":"mod","sub":"Retirar a caixa alta de títulos longos.","ops":["U30","U32"],"c2":{"c":"C17","t":"Revisões automáticas geram alertas demais.","mit":"Só em títulos e botões."},"cf":"Sem intervenção, o portal parece descuidado e a leitura cansa.","lim":{"l":"L06","t":"Depende de o guia ser adotado por todos os redatores."},"ide":{"mais":["I03"],"menos":[]},"ref":"Estaria errada se, em teste, a inconsistência passar despercebida.","conf":"média"},
{"id":166,"h":4,"sev":3,"t":"Uma palavra com dois sentidos","sym":"No app da companhia de energia, “Conta” é o login em uma tela e a fatura em outra.","ten":"A palavra é natural nos dois casos, mas causa confusão lado a lado.","sol":"Separar os conceitos: “Perfil” para o acesso, “Fatura” para a cobrança, em todos os canais.","c":"C08","u":"U09","e":"macro","i":"I03","m":"Contatos por confusão de termos","freq":3,"imp":2,"pers":2,"pf":"P01","hx":["BS7","GP5","DN8","SH1"],"dom":"casa","vul":"idosos","ag":"Ganha: clientes. Perde: nada relevante.","alt":"E se o termo for usado assim por toda a empresa?","esc":{"micro":"Renomear nas telas principais.","meso":"Termos distintos em todo o app.","macro":"Separar os conceitos: “Perfil” para o acesso, “Fatura” para a cobrança, em todos os canais."},"st":"mod","sub":"Retirar “Conta” como rótulo do login.","ops":["U04","U30"],"c2":{"c":"C11","t":"O atendimento continua usando “conta” para as duas coisas.","mit":"Treinar o atendimento no novo vocabulário."},"cf":"Sem intervenção, clientes pagam a fatura errada ou não acham o login.","lim":{"l":"L06","t":"Vocabulário regulado na fatura."},"ide":{"mais":["I03"],"menos":[]},"ref":"Estaria errada se, em teste, os clientes distinguirem login e fatura sem erro apesar do mesmo nome.","conf":"alta"},
{"id":167,"h":4,"sev":2,"t":"Clique simples ou duplo?","sym":"No ambiente virtual, um clique abre o arquivo numa lista; em outra, é preciso clicar duas vezes.","ten":"Cada lista herdou um comportamento diferente.","sol":"Selecionar um comportamento de abertura para todas as listas do produto.","c":"C05","u":"U35","e":"meso","i":"I04","m":"Cliques repetidos sem efeito","freq":2,"imp":1,"pers":2,"pf":"P01","hx":["SH1","BS6","DN5","ISO3"],"dom":"educacao","vul":"","ag":"Ganha: estudantes. Perde: nada relevante.","alt":"E se o clique duplo existir para evitar aberturas acidentais?","esc":{"micro":"Clique simples em todas as listas.","meso":"Selecionar um comportamento de abertura para todas as listas do produto.","macro":"Regra de interação no design system."},"st":"sub","sub":"A própria solução é subtrativa: remove o clique duplo.","ops":["U30","U21"],"c2":{"c":"C27","t":"Aberturas acidentais aumentam.","mit":"Área de clique clara e pequena espera contra toques duplos acidentais."},"cf":"Sem intervenção, cliques repetidos e itens abertos em dobro.","lim":{"l":"L03","t":"Nenhuma barreira técnica."},"ide":{"mais":["I04"],"menos":[]},"ref":"Estaria errada se as aberturas duplicadas forem raras nos registros de uso.","conf":"alta"},
{"id":168,"h":4,"sev":2,"t":"Paginação e rolagem infinita misturadas","sym":"Algumas listas têm páginas; outras carregam sem fim.","ten":"Cada equipe escolheu um padrão.","sol":"Condicionar pelo tipo de tarefa: paginação para procurar, rolagem para explorar, aplicado em todo o produto.","c":"C11","u":"U21","e":"meso","i":"I03","m":"Itens não encontrados","freq":2,"imp":1,"pers":2,"pf":"P07","hx":["SH1","BS6","ISO3","GP6"],"dom":"comercio","vul":"","ag":"Ganha: quem compra. Perde: nada relevante.","alt":"E se cada padrão servir a um tipo de tarefa (navegar × procurar)?","esc":{"micro":"Mesmo padrão em listas semelhantes.","meso":"Condicionar pelo tipo de tarefa: paginação para procurar, rolagem para explorar, aplicado em todo o produto.","macro":"Regra no design system sobre quando usar cada um."},"st":"mod","sub":"Retirar a rolagem infinita de listas onde as pessoas procuram itens.","ops":["U30","U26"],"c2":{"c":"C17","t":"Regras de uso exigem avaliação caso a caso.","mit":"Critérios simples documentados."},"cf":"Sem intervenção, itens não são encontrados.","lim":{"l":"L06","t":"Depende de todas as equipes aplicarem a regra."},"ide":{"mais":["I03"],"menos":[]},"ref":"Estaria errada se, em teste, as pessoas encontrarem itens igualmente bem nas duas formas de lista.","conf":"alta"},
{"id":169,"h":4,"sev":3,"t":"Hambúrguer também no computador","sym":"No portal de notícias, no computador, o menu continua escondido num ícone.","ten":"O padrão mobile foi copiado para uma tela que não precisa dele.","sol":"Navegação visível em telas largas e recolhida só em telas pequenas.","c":"C29","u":"U21","e":"macro","i":"I08","m":"Uso das seções escondidas","freq":2,"imp":2,"pers":2,"pf":"P14","hx":["MB4","LX4","TG16","ISO3"],"dom":"comunicacao","vul":"idosos","ag":"Ganha: leitores no computador. Perde: nada relevante.","alt":"E se o menu escondido for uma escolha de estilo?","esc":{"micro":"Seções principais visíveis no desktop.","meso":"Navegação responsiva: seções visíveis em telas largas e recolhidas só em telas pequenas.","macro":"Navegação visível em telas largas e recolhida só em telas pequenas."},"st":"sub","sub":"A própria solução é subtrativa: remove o hambúrguer em telas largas.","ops":["U35","U26"],"c2":{"c":"C17","t":"Muitas seções visíveis poluem o topo.","mit":"Principais visíveis; restantes em “Mais”."},"cf":"Sem intervenção, seções pouco visitadas.","lim":{"l":"L03","t":"Nenhuma barreira técnica."},"ide":{"mais":["I08"],"menos":[]},"ref":"Estaria errada se as visitas não mudarem.","conf":"alta"},
{"id":170,"h":4,"sev":4,"t":"App e site com funções diferentes","sym":"Pagar boleto funciona no site do banco, mas não no app — sem aviso.","ten":"As plataformas evoluíram separadas, mas a pessoa espera o mesmo serviço.","sol":"Escalonar a paridade: roteiro que leva as funções essenciais aos dois canais, com aviso claro enquanto houver diferença.","c":"C07","u":"U31","e":"macro","i":"I04","m":"Chamados sobre funções ausentes","freq":3,"imp":3,"pers":2,"pf":"P08","hx":["SH1","ISO3","MB6","BS6"],"dom":"financas","vul":"","ag":"Ganha: clientes. Perde: equipes precisam de roteiro comum.","alt":"E se a função for complexa demais para o celular?","esc":{"micro":"Aviso quando a função estiver só em um canal.","meso":"Roteiro de paridade das funções essenciais.","macro":"Escalonar a paridade: roteiro que leva as funções essenciais aos dois canais, com aviso claro enquanto houver diferença."},"st":"add","sub":"Retirar funções duplicadas que divergem entre canais.","ops":["U33","U22"],"c2":{"c":"C31","t":"Paridade atrasa lançamentos.","mit":"Priorizar funções essenciais."},"cf":"Sem intervenção, clientes ficam sem pagar boletos pelo app.","lim":{"l":"L04","t":"Capacidade das equipes."},"ide":{"mais":["I04"],"menos":["I02"]},"ref":"Estaria errada se quase nenhum cliente usar os dois canais para as mesmas tarefas.","conf":"alta"},
{"id":171,"h":4,"sev":2,"t":"Ícones de estilos misturados","sym":"Na ferramenta de IA, uns ícones são contornados, outros preenchidos, de bibliotecas diferentes.","ten":"Os ícones foram sendo adicionados de onde havia.","sol":"Uma única família de ícones, com estilo e espessura padronizados.","c":"C02","u":"U35","e":"micro","i":"I03","m":"Tempo de reconhecimento","freq":1,"imp":1,"pers":3,"pf":"P01","hx":["SH1","TG4","TG18","BS6"],"dom":"ia","vul":"","ag":"Ganha: quem usa a ferramenta. Perde: nada relevante.","alt":"E se ícones de estilos diferentes indicarem recursos de parceiros?","esc":{"micro":"Uma única família de ícones, com estilo e espessura padronizados.","meso":"Família de ícones única.","macro":"Governança da biblioteca de ícones."},"st":"sub","sub":"A própria solução é subtrativa: remove as outras famílias de ícones.","ops":["U30","U12"],"c2":{"c":"C16","t":"Nem toda ação tem ícone na família escolhida.","mit":"Criar os que faltam no mesmo estilo."},"cf":"Sem intervenção, a ferramenta parece improvisada e perde confiança.","lim":{"l":"L04","t":"Custo de redesenhar ícones."},"ide":{"mais":["I03"],"menos":[]},"ref":"Estaria errada se, em teste de confiança, a mistura de ícones não mudar a avaliação da ferramenta.","conf":"média"},
{"id":172,"h":4,"sev":3,"t":"Erros em tons diferentes","sym":"O assistente de IA responde a erros ora com formalidade, ora com piadas, ora culpando a pessoa.","ten":"Cada equipe escreve do seu jeito.","sol":"Capacitar quem escreve: guia de voz e tom com modelos de mensagem de erro para toda a equipe.","c":"C35","u":"U32","e":"macro","i":"I03","m":"Satisfação após erros","freq":2,"imp":2,"pers":2,"pf":"P08","hx":["IA5","BS5.2","SH1","ISO7"],"dom":"ia","vul":"","ag":"Ganha: quem conversa com o assistente. Perde: equipes perdem liberdade de tom.","alt":"E se o tom variar por contexto (erro grave × dica)?","esc":{"micro":"Revisar as mensagens de erro mais vistas.","meso":"Modelos de mensagem por tipo de erro.","macro":"Capacitar quem escreve: guia de voz e tom com modelos de mensagem de erro para toda a equipe."},"st":"mod","sub":"Retirar mensagens com piadas em situações de erro.","ops":["U30","U36"],"c2":{"c":"C21","t":"O tom ideal muda com o público.","mit":"Revisão periódica do guia com exemplos reais das conversas."},"cf":"Sem intervenção, o assistente parece incoerente e pouco confiável.","lim":{"l":"L07","t":"Várias equipes escrevem respostas do assistente de forma independente."},"ide":{"mais":["I03"],"menos":[]},"ref":"Estaria errada se, em teste, as pessoas não perceberem a variação de tom nem mudarem a confiança no assistente.","conf":"média"},
{"id":173,"h":4,"sev":3,"t":"Obrigatório às vezes marcado","sym":"Em um formulário do hospital os obrigatórios têm asterisco; em outro, não — e o leitor de tela não anuncia nenhum.","ten":"A marcação depende de quem fez a tela.","sol":"Padrão único: marcar os opcionais (se forem minoria) ou os obrigatórios, sempre igual.","c":"C22","u":"U30","e":"micro","i":"I04","m":"Envios com campos faltando","freq":3,"imp":2,"pers":2,"pf":"P01","hx":["WC3.3","WC1.3","SH1","BS6"],"dom":"saude","vul":"cegos (leitor de tela)","ag":"Ganha: pacientes, inclusive com leitor de tela. Perde: nada relevante.","alt":"E se a maioria dos campos for obrigatória?","esc":{"micro":"Padrão único: marcar os opcionais (se forem minoria) ou os obrigatórios, sempre igual.","meso":"Padrão em todos os formulários.","macro":"Guia de formulários do hospital: regra única de obrigatoriedade, com texto lido pelo leitor de tela."},"st":"mod","sub":"Retirar o asterisco sem texto alternativo.","ops":["U01","U19"],"c2":{"c":"C17","t":"Marcar todos os campos polui.","mit":"Marcar os opcionais quando forem minoria."},"cf":"Sem intervenção, envios incompletos.","lim":{"l":"L03","t":"Nenhuma barreira técnica."},"ide":{"mais":["I04","I06"],"menos":[]},"ref":"Estaria errada se os envios incompletos forem por outros motivos.","conf":"alta"},
{"id":174,"h":4,"sev":3,"t":"Chave e caixa de seleção para a mesma coisa","sym":"Ativar a rotina de iluminação usa chave numa tela e caixa de seleção noutra, uma aplica na hora, a outra só ao salvar.","ten":"Os dois controles funcionam, mas o significado fica ambíguo.","sol":"Chave para efeito imediato, caixa de seleção para opção que será salva depois.","c":"C04","u":"U21","e":"micro","i":"I03","m":"Configurações não aplicadas","freq":2,"imp":2,"pers":2,"pf":"P01","hx":["DN2","SH1","ISO3","BS3.1"],"dom":"casa","vul":"","ag":"Ganha: quem configura a casa. Perde: nada relevante.","alt":"E se não houver necessidade de “salvar” em nenhuma configuração?","esc":{"micro":"Chave para efeito imediato, caixa de seleção para opção que será salva depois.","meso":"Regra de uso dos dois controles.","macro":"Guia de componentes: chave para efeito imediato, caixa de seleção só em formulários com “Salvar”."},"st":"mod","sub":"Retirar o botão “Salvar” de configurações de efeito imediato.","ops":["U30","U16"],"c2":{"c":"C27","t":"Pessoas acostumadas a salvar ficam inseguras.","mit":"Confirmação discreta do efeito."},"cf":"Sem intervenção, configurações não aplicadas.","lim":{"l":"L03","t":"Nenhuma barreira técnica."},"ide":{"mais":["I03","I04"],"menos":[]},"ref":"Estaria errada se, nos registros, as configurações não aplicadas forem raras.","conf":"alta"},
{"id":175,"h":4,"sev":2,"t":"Link abre ora na mesma aba, ora em outra","sym":"No portal público, alguns links abrem nova aba sem aviso; outros tiram a pessoa do site.","ten":"Não há regra; cada link foi configurado à parte.","sol":"Regra: links internos na mesma aba; externos indicados com ícone.","c":"C27","u":"U21","e":"meso","i":"I04","m":"Abas perdidas","freq":2,"imp":1,"pers":2,"pf":"P01","hx":["WC3.2","SH1","ISO3","TG2"],"dom":"publico","vul":"","ag":"Ganha: cidadãos. Perde: nada relevante.","alt":"E se a nova aba for necessária para não perder formulários?","esc":{"micro":"Ícone de link externo.","meso":"Regra: links internos na mesma aba; externos indicados com ícone.","macro":"Regra do portal: links internos na mesma aba, externos com ícone e aviso."},"st":"mod","sub":"Retirar a abertura em nova aba de links internos.","ops":["U30","U01"],"c2":{"c":"C06","t":"Links internos na mesma aba podem fazer perder um formulário.","mit":"Avisar antes de sair com dados não salvos."},"cf":"Sem intervenção, abas perdidas e sensação de desorientação.","lim":{"l":"L03","t":"Nenhuma barreira técnica."},"ide":{"mais":["I04"],"menos":[]},"ref":"Estaria errada se, em teste, as pessoas não perderem abas nem se desorientarem com os links.","conf":"alta"},
{"id":176,"h":4,"sev":3,"t":"Tabelas que ordenam só às vezes","sym":"Clicar no cabeçalho ordena em uma tabela e não faz nada em outra.","ten":"As tabelas foram construídas com componentes diferentes.","sol":"Componente de tabela único, com ordenação disponível e indicada em todas.","c":"C11","u":"U12","e":"meso","i":"I04","m":"Tentativas de ordenação sem efeito","freq":2,"imp":2,"pers":2,"pf":"P08","hx":["SH1","BS6","DN5","TG4","GP6"],"dom":"trabalho","vul":"","ag":"Ganha: quem analisa dados em várias telas. Perde: equipes perdem tabelas feitas sob medida.","alt":"E se as tabelas diferentes nascerem de necessidades diferentes (edição × leitura)?","esc":{"micro":"Indicador de ordenação em todos os cabeçalhos.","meso":"Componente de tabela único, com ordenação disponível e indicada em todas.","macro":"Componente de tabela único, versionado no design system."},"st":"sub","sub":"A própria solução é subtrativa: remove os componentes de tabela antigos.","ops":["U35","U31"],"c2":{"c":"C12","t":"Um componente único vira gargalo para mudanças urgentes.","mit":"Extensões previstas no componente."},"cf":"Sem intervenção, a pessoa clica em cabeçalhos que não respondem e desiste de ordenar.","lim":{"l":"L04","t":"Tempo de migração das telas antigas."},"ide":{"mais":["I04","I11"],"menos":["I07"]},"ref":"Estaria errada se, nas telas sem ordenação, ninguém tentar ordenar.","conf":"alta"},
{"id":177,"h":4,"sev":2,"t":"Filtros que mudam de lugar","sym":"Na busca de voos os filtros ficam à esquerda; na de hotéis, no topo.","ten":"Cada página foi diagramada isoladamente.","sol":"Separar no espaço de forma estável: posição fixa dos filtros em todas as listagens do mesmo tipo.","c":"C32","u":"U07","e":"meso","i":"I03","m":"Tempo para achar filtros","freq":2,"imp":1,"pers":2,"pf":"P01","hx":["SH1","BS6","BS1.2","LX10"],"dom":"mobilidade","vul":"","ag":"Ganha: quem compara viagens. Perde: nada relevante.","alt":"E se as páginas tiverem filtros tão diferentes que uma posição única não sirva?","esc":{"micro":"Filtros com o mesmo estilo visual.","meso":"Separar no espaço de forma estável: posição fixa dos filtros em todas as listagens do mesmo tipo.","macro":"Regra de layout de listagens no design system."},"st":"mod","sub":"Retirar filtros avulsos espalhados no conteúdo.","ops":["U30","U36"],"c2":{"c":"C16","t":"Em telas pequenas, a coluna lateral não cabe.","mit":"Filtros num painel que abre do mesmo botão."},"cf":"Sem intervenção, a pessoa procura os filtros a cada página.","lim":{"l":"L06","t":"Depende das equipes de cada produto."},"ide":{"mais":["I03"],"menos":[]},"ref":"Estaria errada se as pessoas quase não usarem filtros.","conf":"alta"},
{"id":178,"h":4,"sev":4,"t":"Deslizar com efeito oposto","sym":"No app de e-mail, deslizar para a esquerda arquiva numa caixa e exclui em outra.","ten":"O gesto é invisível, e sua consequência varia.","sol":"Isolar ações destrutivas: um significado por gesto em todo o app, e excluir sempre com desfazer.","c":"C05","u":"U23","e":"micro","i":"I05","m":"Exclusões acidentais por gesto","freq":2,"imp":3,"pers":2,"pf":"P01","hx":["SH1","SH6","DN5","MB3","WC2.5"],"dom":"comunicacao","vul":"idosos","ag":"Ganha: quem lê e-mails no celular, sobretudo idosos. Perde: parte da agilidade dos gestos.","alt":"E se gestos invisíveis forem arriscados em si para ações destrutivas?","esc":{"micro":"Isolar ações destrutivas: um significado por gesto em todo o app, e excluir sempre com desfazer.","meso":"Um significado por gesto no app, com desfazer.","macro":"Diretriz: ações destrutivas nunca num gesto sem confirmação ou desfazer."},"st":"mod","sub":"Retirar a exclusão dos gestos de deslizar.","ops":["U24","U30"],"c2":{"c":"C20","t":"Quem usava o gesto para excluir perde rapidez.","mit":"Gesto configurável, com desfazer."},"cf":"Sem intervenção, e-mails importantes são excluídos por engano.","lim":{"l":"L07","t":"Toques acidentais em telas pequenas."},"ide":{"mais":["I05"],"menos":["I02"]},"ref":"Estaria errada se as exclusões acidentais forem raras em registros de uso.","conf":"alta"},
{"id":179,"h":4,"sev":2,"t":"Valores com e sem “R$”","sym":"Alguns preços aparecem com símbolo, outros sem.","ten":"Os dados vêm de sistemas diferentes.","sol":"Formatação monetária central aplicada a todos os valores.","c":"C15","u":"U12","e":"micro","i":"I04","m":"Dúvidas sobre valores","freq":2,"imp":1,"pers":2,"pf":"P01","hx":["SH1","BS6","GP6","GP9"],"dom":"comercio","vul":"","ag":"Ganha: quem compra. Perde: nada relevante.","alt":"E se os valores sem símbolo forem pontos, e não reais?","esc":{"micro":"Formatação monetária central aplicada a todos os valores.","meso":"Formatação monetária central.","macro":"Padrão de moeda para parceiros."},"st":"sub","sub":"A própria solução é subtrativa: remove as formatações locais.","ops":["U35","U16"],"c2":{"c":"C35","t":"Pontos de fidelidade e reais podem ser confundidos.","mit":"Unidade explícita em cada valor."},"cf":"Sem intervenção, dúvidas sobre valores e pontos.","lim":{"l":"L03","t":"Nenhuma barreira técnica relevante."},"ide":{"mais":["I04"],"menos":[]},"ref":"Estaria errada se, em teste, os clientes lerem os valores corretamente com e sem “R$”.","conf":"alta"},
{"id":180,"h":4,"sev":4,"t":"Foco visível só em algumas telas","sym":"Navegando pelo teclado no ambiente virtual, o destaque de foco some em certas páginas.","ten":"Estilos locais sobrescreveram o padrão.","sol":"Refutar a hipótese de que está tudo acessível: teste automatizado de foco em todas as páginas, com estilo global protegido.","c":"C25","u":"U27","e":"micro","i":"I06","m":"Tarefas concluídas por teclado","freq":2,"imp":3,"pers":2,"pf":"P01","hx":["WC2.4","WC2.1","SH2","TG4"],"dom":"educacao","vul":"deficiência motora","ag":"Ganha: quem navega por teclado. Perde: estilos locais deixam de sobrescrever o foco.","alt":"E se o foco sumir por falta de testes, e não de padrão?","esc":{"micro":"Refutar a hipótese de que está tudo acessível: teste automatizado de foco em todas as páginas, com estilo global protegido.","meso":"Estilo de foco global protegido.","macro":"Teste automatizado de acessibilidade a cada publicação."},"st":"mod","sub":"Retirar os estilos locais que apagam o foco.","ops":["U30","U19"],"c2":{"c":"C31","t":"Testes automatizados atrasam publicações.","mit":"Rodar em paralelo e bloquear só falhas graves."},"cf":"Sem intervenção, quem usa teclado não sabe onde está.","lim":{"l":"L03","t":"Estilos legados que sobrescrevem o foco em páginas antigas."},"ide":{"mais":["I06"],"menos":["I02"]},"ref":"Estaria errada se, em auditoria, o foco estiver visível em todas as páginas.","conf":"alta"},
{"id":181,"h":4,"sev":2,"t":"Páginas antigas com outra identidade","sym":"Parte do portal da prefeitura tem fontes e cores de dez anos atrás.","ten":"Refazer tudo é caro, mas o contraste parece dois produtos.","sol":"Migração gradual por prioridade de uso, com camada visual comum aplicada primeiro.","c":"C36","u":"U33","e":"macro","i":"I11","m":"Telas no padrão novo","freq":2,"imp":1,"pers":3,"pf":"P14","hx":["SH1","TG4","TG18","BS6"],"dom":"publico","vul":"","ag":"Ganha: cidadãos. Perde: o órgão investe numa migração longa.","alt":"E se as páginas antigas forem pouco usadas? Então retirá-las pode ser melhor que migrá-las.","esc":{"micro":"Camada visual comum aplicada às páginas antigas.","meso":"Migração dos serviços mais usados.","macro":"Migração gradual por prioridade de uso, com camada visual comum aplicada primeiro."},"st":"mod","sub":"Retirar do ar páginas antigas pouco visitadas.","ops":["U31","U35"],"c2":{"c":"C31","t":"A migração longa convive com duas identidades por anos.","mit":"Priorizar a migração pelas páginas mais visitadas."},"cf":"Sem intervenção, o portal parece dois produtos e perde credibilidade.","lim":{"l":"L04","t":"Orçamento do órgão para desenvolvimento e revisão de conteúdo."},"ide":{"mais":["I11"],"menos":["I02"]},"ref":"Estaria errada se as páginas antigas não causarem estranhamento.","conf":"média"},
{"id":182,"h":4,"sev":3,"t":"Nome do plano diferente na fatura","sym":"Assinou o “Plano Família” de celular e a fatura cobra “Premium Multi”.","ten":"O financeiro usa nomes internos, mas o cliente reconhece o nome comercial.","sol":"Mesmo nome em página de preços, confirmação, fatura e suporte.","c":"C11","u":"U30","e":"macro","i":"I06","m":"Contestações de cobrança","freq":2,"imp":2,"pers":2,"pf":"P09","hx":["SH1","DP3","ISO3","GP5"],"dom":"comunicacao","vul":"","ag":"Ganha: clientes. Perde: o financeiro perde os nomes internos.","alt":"E se o nome do plano mudar com frequência por marketing?","esc":{"micro":"Mesmo nome na confirmação.","meso":"Mesmo nome comercial na página de preços, na confirmação e na fatura.","macro":"Mesmo nome em página de preços, confirmação, fatura e suporte."},"st":"mod","sub":"Retirar nomes internos da fatura.","ops":["U12","U04"],"c2":{"c":"C21","t":"O marketing renomeia os planos com frequência.","mit":"Nome comercial vinculado ao código do plano."},"cf":"Sem intervenção, contestações de cobrança.","lim":{"l":"L06","t":"Sistema de faturamento legado."},"ide":{"mais":["I06"],"menos":[]},"ref":"Estaria errada se as contestações forem por valor, e não por nome.","conf":"alta"},
{"id":183,"h":4,"sev":2,"t":"Ações de linha em lugares diferentes","sym":"Editar e excluir são botões numa lista e ficam num menu ⋮ em outra.","ten":"Cada lista tem sua solução.","sol":"Rehierarquizar as ações de linha: a principal visível, as demais num menu, igual em todas as listas.","c":"C32","u":"U11","e":"meso","i":"I03","m":"Tempo para achar a ação","freq":2,"imp":1,"pers":2,"pf":"P01","hx":["SH1","BS6","BS1.2","TG4"],"dom":"trabalho","vul":"","ag":"Ganha: quem gerencia listas. Perde: ações secundárias ficam num menu, menos visíveis.","alt":"E se ações diferentes precisarem de visibilidade diferente?","esc":{"micro":"Ação principal visível.","meso":"Rehierarquizar as ações de linha: a principal visível, as demais num menu, igual em todas as listas.","macro":"Padrão de ações por linha documentado no design system, com exemplos de uso."},"st":"mod","sub":"Retirar botões de ação duplicados.","ops":["U30","U35"],"c2":{"c":"C17","t":"Menu esconde ações úteis.","mit":"Ação principal visível; as demais agrupadas num menu com rótulo."},"cf":"Sem intervenção, a pessoa procura as ações em cada lista.","lim":{"l":"L06","t":"Depende de todas as equipes de produto aplicarem o padrão."},"ide":{"mais":["I03"],"menos":["I09"]},"ref":"Estaria errada se as pessoas acharem as ações rápido.","conf":"alta"},
{"id":184,"h":4,"sev":2,"t":"Confirmação ora em aviso, ora em página","sym":"No portal do paciente, às vezes o sucesso é um aviso rápido; às vezes uma página inteira.","ten":"Não há critério sobre quando usar cada um.","sol":"Condicionar pelo peso da ação: aviso rápido para ações simples; página com comprovante para marcos.","c":"C24","u":"U21","e":"meso","i":"I03","m":"Dúvidas sobre conclusão","freq":2,"imp":1,"pers":2,"pf":"P01","hx":["SH4","SH1","BS6","ISO3"],"dom":"saude","vul":"","ag":"Ganha: pacientes. Perde: nada relevante.","alt":"E se a pessoa precisar de comprovante em todos os casos?","esc":{"micro":"Regra documentada de quando usar aviso rápido e quando usar página.","meso":"Condicionar pelo peso da ação: aviso rápido para ações simples; página com comprovante para marcos.","macro":"Padrão de confirmações no design system da rede de saúde, com exemplos."},"st":"mod","sub":"Retirar páginas de sucesso de ações simples.","ops":["U30","U04"],"c2":{"c":"C34","t":"Aviso rápido some e a pessoa perde o comprovante.","mit":"Registro na área de histórico."},"cf":"Sem intervenção, dúvida sobre a conclusão.","lim":{"l":"L03","t":"Nenhuma barreira técnica relevante."},"ide":{"mais":["I03"],"menos":[]},"ref":"Estaria errada se, em teste, os pacientes souberem que concluíram a ação nos dois formatos.","conf":"alta"},
{"id":185,"h":4,"sev":3,"t":"Busca global que não busca tudo","sym":"O assistente de IA da empresa busca em documentos, mas não em e-mails nem em chats — sem avisar.","ten":"Cada módulo tem seu índice, mas a pessoa espera uma busca única.","sol":"Redelimitar a busca: unificada entre as fontes permitidas, dizendo claramente onde procurou.","c":"C07","u":"U05","e":"macro","i":"I01","m":"Buscas sem resultado","freq":3,"imp":2,"pers":2,"pf":"P03","hx":["IA1","SH1","ISO1","GP3"],"dom":"ia","vul":"","ag":"Ganha: quem busca informações. Perde: exige indexar mais fontes.","alt":"E se nem toda fonte puder ser indexada por privacidade?","esc":{"micro":"Aviso das fontes pesquisadas.","meso":"Busca em documentos e e-mails.","macro":"Redelimitar a busca: unificada entre as fontes permitidas, dizendo claramente onde procurou."},"st":"add","sub":"Retirar a promessa de busca “em tudo”.","ops":["U01","U12"],"c2":{"c":"C05","t":"Indexar e-mails expõe dados sensíveis.","mit":"Respeitar as permissões de cada pessoa ao indexar e-mails e chats."},"cf":"Sem intervenção, a pessoa acha que a informação não existe.","lim":{"l":"L06","t":"Leis de privacidade e políticas internas de acesso a comunicações."},"ide":{"mais":["I01"],"menos":["I05"]},"ref":"Estaria errada se as buscas malsucedidas forem por informações que não estão em e-mails nem chats.","conf":"média"},
{"id":186,"h":4,"sev":4,"t":"Remover ou apagar?","sym":"No app de mensagens, “Remover” às vezes tira a pessoa do grupo, às vezes apaga a mensagem para todos.","ten":"As palavras parecem sinônimas, mas o efeito é diferente.","sol":"Separar os conceitos: “Remover do grupo” para desvincular, “Apagar para todos” para excluir, sempre com o efeito dito ao lado.","c":"C08","u":"U09","e":"micro","i":"I05","m":"Exclusões inesperadas","freq":2,"imp":3,"pers":2,"pf":"P01","hx":["BS7","GP5","SH5","DN8"],"dom":"comunicacao","vul":"idosos","ag":"Ganha: quem administra grupos, sobretudo idosos. Perde: nada relevante.","alt":"E se o problema for a ação destrutiva não ter desfazer, e não só o nome?","esc":{"micro":"Separar os conceitos: “Remover do grupo” para desvincular, “Apagar para todos” para excluir, sempre com o efeito dito ao lado.","meso":"Texto de efeito ao lado de cada opção (“sai só para você” / “apaga para todos”).","macro":"Glossário de ações destrutivas aplicado a todos os produtos da empresa."},"st":"mod","sub":"Retirar “Remover” das ações que apagam conteúdo para outras pessoas.","ops":["U30","U24"],"c2":{"c":"C11","t":"Palavras novas confundem quem já tinha aprendido as antigas.","mit":"Mostrar o efeito junto do rótulo durante a transição."},"cf":"Sem intervenção, mensagens são apagadas para o grupo inteiro por engano.","lim":{"l":"L07","t":"Hábitos formados com a versão anterior."},"ide":{"mais":["I05"],"menos":[]},"ref":"Estaria errada se, nos registros, “Remover” quase nunca for seguido de pedido de recuperação.","conf":"alta"},
{"id":187,"h":4,"sev":1,"t":"Informação e ajuda com o mesmo ícone","sym":"No portal do paciente, o “i” e o “?” são usados de forma intercambiável.","ten":"Os ícones parecem equivalentes, mas indicam coisas diferentes.","sol":"Separar funções: “i” explica o dado (ex.: faixa de referência do exame), “?” ensina o uso da tela.","c":"C35","u":"U09","e":"micro","i":"I03","m":"Uso dos ícones de ajuda","freq":1,"imp":1,"pers":2,"pf":"P01","hx":["BS7","SH1","GP5","DN7"],"dom":"saude","vul":"","ag":"Ganha: pacientes. Perde: nada relevante.","alt":"E se um único ícone de ajuda contextual bastasse para os dois usos?","esc":{"micro":"Separar funções: “i” explica o dado (ex.: faixa de referência do exame), “?” ensina o uso da tela.","meso":"Inventário dos ícones de ajuda no portal, com regra de uso.","macro":"Biblioteca de ícones da rede de saúde com significados documentados."},"st":"mod","sub":"Retirar um dos dois ícones onde a distinção não for necessária.","ops":["U30","U04"],"c2":{"c":"C17","t":"Unificar em um só ícone perde a diferença entre explicar o dado e ensinar o uso.","mit":"Rótulo curto no balão (“Sobre este valor”, “Como usar”)."},"cf":"Sem intervenção, pacientes abrem a ajuda errada e desistem de entender o exame.","lim":{"l":"L06","t":"Depende de acordo entre as equipes do portal."},"ide":{"mais":["I03"],"menos":[]},"ref":"Estaria errada se, em teste, os pacientes não perceberem diferença entre os ícones e não se confundirem com isso.","conf":"alta"},
{"id":188,"h":4,"sev":2,"t":"Formulários de uma e duas colunas","sym":"No portal, uns formulários são em coluna única, outros em duas, sem motivo aparente.","ten":"Cada designer escolheu uma disposição.","sol":"Comparar os dois layouts com cidadãos e adotar coluna única como padrão, com duas só para campos curtos relacionados.","c":"C23","u":"U26","e":"meso","i":"I02","m":"Tempo de preenchimento","freq":2,"imp":1,"pers":2,"pf":"P07","hx":["BS1.2","SH1","GP6","ISO1"],"dom":"publico","vul":"","ag":"Ganha: cidadãos que preenchem formulários. Perde: páginas ficam mais longas.","alt":"E se duas colunas forem úteis para campos curtos relacionados (cidade e UF)?","esc":{"micro":"Coluna única nos formulários mais usados.","meso":"Comparar os dois layouts com cidadãos e adotar coluna única como padrão, com duas só para campos curtos relacionados.","macro":"Diretriz de formulários do governo digital com exemplos."},"st":"mod","sub":"Retirar o layout de duas colunas dos formulários longos.","ops":["U30","U21"],"c2":{"c":"C16","t":"Coluna única alonga a página no computador.","mit":"Agrupar campos em seções curtas com títulos."},"cf":"Sem intervenção, campos da segunda coluna são pulados e os pedidos voltam incompletos.","lim":{"l":"L06","t":"Depende de cada órgão adotar a diretriz."},"ide":{"mais":["I02"],"menos":["I03"]},"ref":"Estaria errada se o teste comparativo mostrar o mesmo tempo e os mesmos erros nos dois layouts.","conf":"alta"},
{"id":189,"h":4,"sev":2,"t":"Unidades misturadas","sym":"O app de energia mostra o consumo em kWh numa tela e em Wh em outra.","ten":"Os dados vêm de fontes diferentes, sem padronização.","sol":"Converter para uma unidade padrão por grandeza, exibida igual em todas as telas.","c":"C35","u":"U16","e":"micro","i":"I04","m":"Erros de quantidade","freq":2,"imp":1,"pers":2,"pf":"P01","hx":["GP6","SH1","MB2","GP4"],"dom":"casa","vul":"","ag":"Ganha: quem acompanha o consumo de energia. Perde: nada relevante.","alt":"E se a unidade certa depender da ordem de grandeza (Wh por hora, kWh por mês)?","esc":{"micro":"Converter para uma unidade padrão por grandeza, exibida igual em todas as telas.","meso":"Unidade padrão por período (kWh no mês, com equivalência em reais).","macro":"Padrão de unidades entre o app, a fatura e o medidor inteligente."},"st":"mod","sub":"Retirar a mistura de unidades na mesma tela.","ops":["U12","U30"],"c2":{"c":"C33","t":"Números muito pequenos em kWh parecem zero no consumo por hora.","mit":"Duas casas decimais e comparação com um aparelho conhecido."},"cf":"Sem intervenção, a pessoa acha que o consumo subiu mil vezes e liga para a distribuidora.","lim":{"l":"L06","t":"A fatura segue unidade definida pela regulação."},"ide":{"mais":["I04"],"menos":[]},"ref":"Estaria errada se, em teste, as pessoas lerem os valores corretamente apesar das unidades diferentes.","conf":"alta"},
{"id":190,"h":4,"sev":4,"t":"Pagamento em tela de outra aparência","sym":"Ao pagar a reserva de hotel, a pessoa é levada a uma página com outra marca e desconfia.","ten":"O processador de pagamentos é externo, mas a confiança é do produto.","sol":"Reacoplar o pagamento à identidade da empresa: pagamento integrado, com aviso claro de quem processa.","c":"C03","u":"U12","e":"macro","i":"I05","m":"Abandono no pagamento","freq":3,"imp":3,"pers":2,"pf":"P01","hx":["SH1","TG18","ISO7","DP4"],"dom":"mobilidade","vul":"","ag":"Ganha: viajantes, que confiam no pagamento. Perde: a integração custa mais que o redirecionamento.","alt":"E se o processador de pagamento exigir página própria por segurança?","esc":{"micro":"Aviso “Você será levado ao ambiente seguro da X” antes de sair.","meso":"Página de pagamento com a identidade da empresa, hospedada pelo processador.","macro":"Reacoplar o pagamento à identidade da empresa: pagamento integrado, com aviso claro de quem processa."},"st":"add","sub":"Retirar redirecionamentos desnecessários entre a reserva e o pagamento.","ops":["U30","U01"],"c2":{"c":"C05","t":"Integrar o pagamento na página amplia a responsabilidade sobre dados de cartão.","mit":"Campos do processador embutidos, com certificação."},"cf":"Sem intervenção, pessoas abandonam a reserva por medo de golpe.","lim":{"l":"L06","t":"Normas de segurança de dados de cartão."},"ide":{"mais":["I05"],"menos":["I02"]},"ref":"Estaria errada se o abandono na etapa de pagamento for igual ao de concorrentes com pagamento integrado.","conf":"alta"},
{"id":191,"h":4,"sev":2,"t":"Navegação que muda de itens","sym":"No site da faculdade, o menu principal tem itens diferentes em cada seção.","ten":"Cada seção quis destacar o que era seu.","sol":"Rehierarquizar: navegação global fixa e itens de cada seção num segundo nível.","c":"C06","u":"U11","e":"meso","i":"I03","m":"Pessoas perdidas na navegação","freq":2,"imp":1,"pers":2,"pf":"P01","hx":["TG16","SH1","BS6","WC3.2"],"dom":"educacao","vul":"","ag":"Ganha: estudantes e visitantes. Perde: itens de cada seção ficam menos visíveis.","alt":"E se as seções forem sites de departamentos com necessidades próprias?","esc":{"micro":"Menu global fixo nas páginas mais visitadas.","meso":"Rehierarquizar: navegação global fixa e itens de cada seção num segundo nível.","macro":"Governança do portal: menu global definido pela comunicação institucional."},"st":"sub","sub":"Retirar os itens locais do menu global.","ops":["U30","U35"],"c2":{"c":"C17","t":"Itens de departamentos ficam menos visíveis.","mit":"Segundo nível de navegação dentro de cada seção."},"cf":"Sem intervenção, estudantes se perdem ao passar de uma seção a outra.","lim":{"l":"L06","t":"Disputa entre departamentos por espaço."},"ide":{"mais":["I03"],"menos":["I09"]},"ref":"Estaria errada se a análise de navegação mostrar poucas passagens entre seções.","conf":"alta"},
{"id":192,"h":4,"sev":4,"t":"Avisos, alertas e erros da mesma cor","sym":"No sistema do hospital, uma informação neutra e um alerta de alergia grave são amarelos.","ten":"A paleta tem poucas cores e todas foram usadas para tudo.","sol":"Redundar sinais: cores semânticas distintas, cada uma com ícone e rótulo próprios.","c":"C01","u":"U22","e":"micro","i":"I05","m":"Alertas ignorados","freq":2,"imp":3,"pers":2,"pf":"P01","hx":["TG3","WC1.4","GP9","GP10"],"dom":"saude","vul":"daltonismo","ag":"Ganha: equipes de saúde e pacientes. Perde: mais cores e ícones para aprender.","alt":"E se o problema for haver alertas demais, que dessensibilizam a equipe?","esc":{"micro":"Redundar sinais: cores semânticas distintas, cada uma com ícone e rótulo próprios.","meso":"Cores e ícones distintos para informação, aviso, erro e alerta clínico.","macro":"Política de alertas clínicos: só os críticos interrompem."},"st":"add","sub":"Retirar alertas informativos do mesmo espaço dos alertas críticos.","ops":["U30","U35"],"c2":{"c":"C17","t":"Mais cores e ícones poluem a tela.","mit":"Poucas categorias, bem distintas."},"cf":"Sem intervenção, um alerta de alergia grave passa despercebido entre avisos rotineiros.","lim":{"l":"L06","t":"Protocolos de segurança do paciente."},"ide":{"mais":["I05"],"menos":["I03"]},"ref":"Estaria errada se, em simulação, a equipe identificar os alertas graves sem dificuldade.","conf":"alta"},
{"id":193,"h":4,"sev":3,"t":"Enter envia ou quebra linha?","sym":"No chat com a IA, Enter envia; no chat de suporte do mesmo produto, quebra linha.","ten":"Cada campo foi implementado separadamente.","sol":"Expor a regra: comportamento único, com a dica visível (“Shift+Enter para nova linha”).","c":"C05","u":"U01","e":"micro","i":"I04","m":"Mensagens enviadas incompletas","freq":2,"imp":2,"pers":2,"pf":"P01","hx":["SH1","DN5","IA7","ISO3"],"dom":"ia","vul":"","ag":"Ganha: quem conversa com a IA. Perde: nada relevante.","alt":"E se cada chat tiver um uso diferente (mensagens curtas × textos longos)?","esc":{"micro":"Expor a regra: comportamento único, com a dica visível (“Shift+Enter para nova linha”).","meso":"Comportamento único de Enter em todos os chats do produto.","macro":"Diretriz de campos de mensagem no design system."},"st":"mod","sub":"Retirar a diferença de comportamento entre os chats.","ops":["U30","U21"],"c2":{"c":"C21","t":"Quem escreve textos longos prefere Enter para quebrar linha.","mit":"Preferência configurável, lembrada por pessoa."},"cf":"Sem intervenção, mensagens incompletas são enviadas à IA e geram respostas inúteis.","lim":{"l":"L03","t":"Nenhuma barreira técnica relevante."},"ide":{"mais":["I04"],"menos":[]},"ref":"Estaria errada se, nos registros, quase não houver mensagens enviadas pela metade.","conf":"alta"},
{"id":194,"h":4,"sev":2,"t":"Cabeçalhos de página diferentes","sym":"Cada página do site de passagens tem título em tamanho, peso e nível diferentes.","ten":"Os estilos foram criados página a página.","sol":"Selecionar um estilo de título por nível e aplicá-lo a todas as páginas.","c":"C10","u":"U35","e":"micro","i":"I03","m":"Inconsistências por auditoria","freq":1,"imp":1,"pers":3,"pf":"P01","hx":["SH1","WC1.3","WC2.4","BS6"],"dom":"mobilidade","vul":"cegos (leitor de tela)","ag":"Ganha: quem navega por títulos com leitor de tela. Perde: nada relevante.","alt":"E se as páginas forem geradas por sistemas diferentes, cada um com seu modelo?","esc":{"micro":"Selecionar um estilo de título por nível e aplicá-lo a todas as páginas.","meso":"Hierarquia de títulos definida no design system.","macro":"Validação automática de hierarquia em todas as publicações."},"st":"sub","sub":"A própria solução é subtrativa: remove os estilos de título locais.","ops":["U30","U12"],"c2":{"c":"C12","t":"Mudar o estilo global pode quebrar páginas antigas.","mit":"Testes visuais antes de publicar."},"cf":"Sem intervenção, quem usa leitor de tela não consegue navegar pelos títulos.","lim":{"l":"L04","t":"Páginas antigas em sistemas diferentes."},"ide":{"mais":["I03","I06"],"menos":[]},"ref":"Estaria errada se o leitor de tela navegar bem apesar dos estilos diferentes.","conf":"alta"},
{"id":195,"h":4,"sev":1,"t":"Datas relativas e absolutas misturadas","sym":"Na mesma lista de notícias: “há 2 horas”, “22/09” e “ontem”.","ten":"Cada formato tem vantagens, mas misturados confundem a ordem.","sol":"Regra única: relativa até 7 dias, absoluta depois, com data completa ao passar o cursor.","c":"C15","u":"U30","e":"micro","i":"I03","m":"Leitura errada da ordem","freq":1,"imp":1,"pers":2,"pf":"P01","hx":["SH1","GP2","BS6","WC3.2"],"dom":"comunicacao","vul":"","ag":"Ganha: quem acompanha conversas e notícias. Perde: nada relevante.","alt":"E se a data relativa for mais útil para o que é recente e a absoluta para o antigo?","esc":{"micro":"Regra única: relativa até 7 dias, absoluta depois, com data completa ao passar o cursor.","meso":"Regra única de datas em todas as listas.","macro":"Formatador de datas compartilhado pelos produtos."},"st":"mod","sub":"Retirar a mistura de formatos numa mesma lista.","ops":["U21","U01"],"c2":{"c":"C21","t":"Uma regra fixa não serve a toda lista (agenda × histórico).","mit":"Exceções documentadas."},"cf":"Sem intervenção, a ordem dos itens é lida errado.","lim":{"l":"L03","t":"Nenhuma barreira técnica relevante."},"ide":{"mais":["I03"],"menos":[]},"ref":"Estaria errada se, em teste, as pessoas ordenarem os itens corretamente apesar da mistura.","conf":"alta"},
{"id":196,"h":4,"sev":3,"t":"Salvar automático em umas telas, manual em outras","sym":"No app de automação da casa, as cenas salvam sozinhas, mas as rotinas exigem botão “Salvar”.","ten":"Os dois modelos coexistem sem aviso.","sol":"Converter o meio: salvar deixa de ser ação da pessoa em todas as telas.","c":"C27","u":"U16","e":"meso","i":"I04","m":"Perdas por não salvar","freq":2,"imp":2,"pers":2,"pf":"P01","hx":["SH1","TG13","DN2","ISO3"],"dom":"casa","vul":"","ag":"Ganha: quem configura a casa. Perde: alterações indesejadas também são gravadas automaticamente.","alt":"E se o salvamento manual existir para permitir testar antes de ativar?","esc":{"micro":"Indicador de “salvo” em todas as telas.","meso":"Converter o meio: salvar deixa de ser ação da pessoa em todas as telas.","macro":"Salvamento automático como padrão da plataforma."},"st":"sub","sub":"Retirar o salvamento manual das rotinas.","ops":["U30","U36"],"c2":{"c":"C08","t":"Salvar tudo automaticamente grava também testes que a pessoa queria descartar.","mit":"Rotinas começam desativadas e têm desfazer."},"cf":"Sem intervenção, rotinas configuradas se perdem e a pessoa desconfia do app.","lim":{"l":"L03","t":"Rotinas antigas podem depender do modelo manual."},"ide":{"mais":["I04"],"menos":["I10"]},"ref":"Estaria errada se as perdas vierem de falhas de rede, e não do modelo de salvamento.","conf":"alta"},
{"id":197,"h":4,"sev":2,"t":"PDF gerado sem a identidade do produto","sym":"O extrato em PDF tem layout e termos diferentes da tela do app.","ten":"A exportação foi feita por outro sistema.","sol":"Reacoplar documento e interface: modelos de PDF gerados pelo mesmo sistema de design e vocabulário.","c":"C12","u":"U12","e":"macro","i":"I03","m":"Dúvidas sobre relatórios exportados","freq":1,"imp":1,"pers":3,"pf":"P01","hx":["SH1","GP5","BS6","ISO3"],"dom":"financas","vul":"","ag":"Ganha: clientes. Perde: nada relevante.","alt":"E se o PDF tiver campos exigidos por lei que a tela não mostra?","esc":{"micro":"Mesmos termos na tela e no PDF.","meso":"Modelo de documento com a mesma estrutura da tela.","macro":"Reacoplar documento e interface: modelos de PDF gerados pelo mesmo sistema de design e vocabulário."},"st":"mod","sub":"Retirar termos diferentes entre tela e documento.","ops":["U30","U36"],"c2":{"c":"C23","t":"Normas exigem termos específicos no documento.","mit":"Termo exigido no documento com o termo da tela entre parênteses."},"cf":"Sem intervenção, clientes não reconhecem no PDF o que viram no app.","lim":{"l":"L06","t":"Normas bancárias sobre extratos."},"ide":{"mais":["I03"],"menos":[]},"ref":"Estaria errada se, em teste, os clientes relacionarem tela e PDF sem esforço.","conf":"alta"},
{"id":198,"h":4,"sev":1,"t":"Cor da mesma pessoa varia","sym":"No sistema da empresa, o avatar de uma colega é azul numa tela e verde em outra.","ten":"A cor é gerada ao acaso a cada tela.","sol":"Inferir a cor do identificador da pessoa, sempre a mesma em todas as telas.","c":"C09","u":"U02","e":"micro","i":"I04","m":"Confusões de autoria","freq":1,"imp":1,"pers":2,"pf":"P01","hx":["SH1","GP9","BS6","TG4"],"dom":"trabalho","vul":"","ag":"Ganha: equipes. Perde: nada relevante.","alt":"E se a cor for escolha pessoal de cada pessoa?","esc":{"micro":"Inferir a cor do identificador da pessoa, sempre a mesma em todas as telas.","meso":"Cor derivada do identificador em todo o produto.","macro":"Paleta de avatares padronizada e acessível."},"st":"mod","sub":"Retirar a cor aleatória a cada tela.","ops":["U30","U12"],"c2":{"c":"C02","t":"Cores derivadas podem ficar parecidas entre colegas.","mit":"Iniciais e foto junto à cor."},"cf":"Sem intervenção, autorias são confundidas.","lim":{"l":"L03","t":"Nenhuma barreira técnica relevante."},"ide":{"mais":["I04"],"menos":[]},"ref":"Estaria errada se as pessoas se guiarem pelo nome, e não pela cor.","conf":"alta"},
{"id":199,"h":4,"sev":3,"t":"Seletores de data diferentes","sym":"Na reserva de voo e na de hotel do mesmo site, os calendários funcionam de jeitos diferentes.","ten":"Bibliotecas diferentes foram incluídas ao longo do tempo.","sol":"Escalonar a unificação: um componente de data único, adotado primeiro nos fluxos mais usados.","c":"C12","u":"U31","e":"meso","i":"I04","m":"Erros de data","freq":2,"imp":2,"pers":2,"pf":"P08","hx":["SH1","BS6","DN5","BS5.1"],"dom":"mobilidade","vul":"","ag":"Ganha: viajantes. Perde: nada relevante.","alt":"E se cada seletor atender a um caso (datas de ida e volta × diárias)?","esc":{"micro":"Mesmo estilo visual nos dois calendários.","meso":"Escalonar a unificação: um componente de data único, adotado primeiro nos fluxos mais usados.","macro":"Componente de data único, com modos (intervalo, data única)."},"st":"sub","sub":"Retirar os seletores extras.","ops":["U12","U35"],"c2":{"c":"C31","t":"A migração de todos os fluxos é lenta.","mit":"Priorizar os fluxos mais usados."},"cf":"Sem intervenção, erros de data em reservas.","lim":{"l":"L04","t":"Tempo de desenvolvimento."},"ide":{"mais":["I04"],"menos":[]},"ref":"Estaria errada se os erros de data vierem de outras causas (fuso, formato).","conf":"alta"},
{"id":200,"h":4,"sev":1,"t":"Desabilitado ora some, ora fica cinza","sym":"Na loja, a opção indisponível às vezes desaparece; às vezes aparece esmaecida.","ten":"Não há regra para indisponibilidade.","sol":"Reenquadrar a indisponibilidade: esmaecido com o motivo quando pode ser desbloqueada; oculto quando nunca estará disponível.","c":"C27","u":"U04","e":"micro","i":"I03","m":"Buscas por opções ocultas","freq":1,"imp":1,"pers":2,"pf":"P01","hx":["SH1","TG6","WC3.2","ISO2"],"dom":"comercio","vul":"","ag":"Ganha: quem compra. Perde: nada relevante.","alt":"E se a opção nunca estiver disponível para aquela pessoa?","esc":{"micro":"Reenquadrar a indisponibilidade: esmaecido com o motivo quando pode ser desbloqueada; oculto quando nunca estará disponível.","meso":"Regra de indisponibilidade no design system.","macro":"Guia de estados de componentes."},"st":"mod","sub":"Retirar opções ocultas quando a pessoa pode desbloqueá-las.","ops":["U30","U01"],"c2":{"c":"C17","t":"Opções esmaecidas demais poluem a tela.","mit":"Ocultar as que nunca estarão disponíveis."},"cf":"Sem intervenção, buscas por opções que parecem ter sumido.","lim":{"l":"L03","t":"Nenhuma barreira técnica relevante."},"ide":{"mais":["I03"],"menos":[]},"ref":"Estaria errada se as buscas por opções ocultas forem raras.","conf":"alta"}
);
